1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
mux: mmio: fix regmap leak on probe failure

The mmio regmap that may be allocated during probe is never freed.

Switch to using the device managed allocator so that the regmap is
released on probe failures (e.g. probe deferral) and on driver unbind.

Fixes: 61de83fd8256 ("mux: mmio: Do not use syscon helper to build regmap")
Cc: stable@vger.kernel.org	# 6.16
Cc: Andrew Davis <afd@ti.com>
Signed-off-by: Johan Hovold <johan@kernel.org>
Acked-by: Andrew Davis <afd@ti.com>
Link: https://patch.msgid.link/20251127134702.1915-1-johan@kernel.org
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The driver used `regmap_init_mmio()` (non-managed) to allocate a regmap, but never released it on probe failures (e.g., probe deferral) or driver unbind, causing a resource leak.

Here is the patch:

 static int mux_mmio_probe(struct platform_device *pdev)
 {
 	struct device *dev = &pdev->dev;
 	struct device_node *np = dev->of_node;
 	struct mux_chip *mux_chip;
 	struct mux_mmio *mux_mmio;
 	struct regmap *regmap;
 	void __iomem *base;
 	int num_fields;
 	int ret;
 	int i;

 	if (of_device_is_compatible(np, "mmio-mux")) {
 		regmap = syscon_node_to_regmap(np->parent);
 	} else {
 		base = devm_platform_ioremap_resource(pdev, 0);
 		if (IS_ERR(base))
 			regmap = ERR_PTR(-ENODEV);
 		else
-			regmap = regmap_init_mmio(dev, base, &mux_mmio_regmap_cfg);
+			regmap = devm_regmap_init_mmio(dev, base, &mux_mmio_regmap_cfg);
 		/* Fallback to checking the parent node on "real" errors. */
 		if (IS_ERR(regmap) && regmap != ERR_PTR(-EPROBE_DEFER)) {
 			regmap = dev_get_regmap(dev->parent, NULL);
 			if (!regmap)
 				regmap = ERR_PTR(-ENODEV);
 		}
 	}
 	if (IS_ERR(regmap))
 		return dev_err_probe(dev, PTR_ERR(regmap),
 				     "failed to get regmap\n");

 	ret = of_property_count_u32_elems(np, "mux-reg-masks");
 	if (ret == 0 || ret % 2)
 		ret = -EINVAL;
 	if (ret < 0) {
 		dev_err(dev, "mux-reg-masks property missing or invalid: %d\n",
 			ret);
 		return ret;
 	}
 	num_fields = ret / 2;

 	mux_chip = devm_mux_chip_alloc(dev, num_fields, sizeof(struct mux_mmio));
 	if (IS_ERR(mux_chip))
 		return PTR_ERR(mux_chip);

 	mux_mmio = mux_chip_priv(mux_chip);

 	mux_mmio->fields = devm_kmalloc(dev, num_fields * sizeof(*mux_mmio->fields), GFP_KERNEL);
 	if (!mux_mmio->fields)
 		return -ENOMEM;

 	mux_mmio->hardware_states = devm_kmalloc(dev, num_fields *
 						 sizeof(*mux_mmio->hardware_states), GFP_KERNEL);
 	if (!mux_mmio->hardware_states)
 		return -ENOMEM;

 	for (i = 0; i < num_fields; i++) {
 		struct mux_control *mux = &mux_chip->mux[i];
 		struct reg_field field;
 		s32 idle_state = MUX_IDLE_AS_IS;
 		u32 reg, mask;
 		int bits;

 		ret = of_property_read_u32_index(np, "mux-reg-masks",
 						 2 * i, &reg);
 		if (!ret)
 			ret = of_property_read_u32_index(np, "mux-reg-masks",
 							 2 * i + 1, &mask);
 		if (ret < 0) {
 			dev_err(dev, "bitfield %d: failed to read mux-reg-masks property: %d\n",
 				i, ret);
 			return ret;
 		}

 		field.reg = reg;
 		field.msb = fls(mask) - 1;
 		field.lsb = ffs(mask) - 1;

 		if (mask != GENMASK(field.msb, field.lsb)) {
 			dev_err(dev, "bitfield %d: invalid mask 0x%x\n",
 				i, mask);
 			return -EINVAL;
 		}

 		mux_mmio->fields[i] = devm_regmap_field_alloc(dev, regmap, field);
 		if (IS_ERR(mux_mmio->fields[i])) {
 			ret = PTR_ERR(mux_mmio->fields[i]);
 			dev_err(dev, "bitfield %d: failed to allocate: %d\n",
 				i, ret);
 			return ret;
 		}

 		bits = 1 + field.msb - field.lsb;
 		mux->states = 1 << bits;

 		of_property_read_u32_index(np, "idle-states", i,
 					   (u32 *)&idle_state);
 		if (idle_state != MUX_IDLE_AS_IS) {
 			if (idle_state < 0 || idle_state >= mux->states) {
 				dev_err(dev, "bitfield: %d: out of range idle state %d\n",
 					i, idle_state);
 				return -EINVAL;
 			}

 			mux->idle_state = idle_state;
 		}
 	}

 	mux_chip->ops = &mux_mmio_ops;

 	dev_set_drvdata(dev, mux_chip);

 	return devm_mux_chip_register(dev, mux_chip);
 }



